import { selectBuilderAdvancedSettings } from "../instance-ui-state/instance-ui-state.selectors.js";
import { registerClientCapability } from "./registry.js";
registerClientCapability({
  name: "agent-fs",
  stateless: true,
  selectPayload: (state, conversationId) => {
    const on = selectBuilderAdvancedSettings(conversationId)(state)?.agentFs ?? false;
    return on ? {} : null;
  }
});
