import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { mergeJsonColumn } from "@ai-matrx/data/db";
import { waitForConversationPersisted } from "./conversation-persistence.js";
import { hasBrowserSession } from "../../../../host/identity.js";
const SURFACE_OWNS_OUTPUT_METADATA_KEY = "surface_owns_output";
const ENGINEERED_INPUTS_METADATA_KEY = "engineered_inputs";
function parsePersistedFlag(metadata, key) {
  if (!metadata || typeof metadata !== "object" || Array.isArray(metadata)) {
    return false;
  }
  return Reflect.get(metadata, key) === true;
}
function parsePersistedSurfaceOwnsOutput(metadata) {
  return parsePersistedFlag(metadata, SURFACE_OWNS_OUTPUT_METADATA_KEY);
}
function parsePersistedEngineeredInputs(metadata) {
  return parsePersistedFlag(metadata, ENGINEERED_INPUTS_METADATA_KEY);
}
const persistConversationFlag = createAsyncThunk("conversations/persistConversationFlag", async ({ conversationId, flag }) => {
  if (!await hasBrowserSession()) return;
  const persisted = await waitForConversationPersisted(conversationId);
  if (!persisted) {
    console.error(
      `[conversation-flag] Conversation ${conversationId} never materialised \u2014 its ${flag} flag could not be saved and will be lost on reopen.`
    );
    return;
  }
  const result = await mergeJsonColumn({
    fetchCurrent: () => supabase.schema("chat").from("conversation").select("id, version, metadata").eq("id", conversationId).is("deleted_at", null).maybeSingle(),
    readColumn: (row) => row.metadata,
    merge: (current) => ({
      ...current,
      [flag]: true
    }),
    applyUpdate: ({ value, expectedVersion, nextVersion }) => supabase.schema("chat").from("conversation").update({ metadata: value, version: nextVersion }).eq("id", conversationId).eq("version", expectedVersion).select("id, version, metadata").maybeSingle()
  });
  if (result.status !== "saved") {
    console.error(
      `[conversation-flag] Failed to persist ${flag} on ${conversationId}: ` + (result.status === "error" ? String(result.error) : `metadata write ${result.status}`) + ". It will be lost on reopen."
    );
  }
});
export {
  ENGINEERED_INPUTS_METADATA_KEY,
  SURFACE_OWNS_OUTPUT_METADATA_KEY,
  parsePersistedEngineeredInputs,
  parsePersistedSurfaceOwnsOutput,
  persistConversationFlag
};
