function assertConversationIdMatches(localConversationId, incomingId, source) {
  if (!incomingId) return;
  if (incomingId === localConversationId) return;
  const message = `[conversation-id drift] server returned a different conversation id via ${source}. local=${localConversationId} incoming=${incomingId}. The server must honor the client-generated conversation id.`;
  if (process.env.NODE_ENV !== "production") {
    throw new Error(message);
  }
  console.error(message);
}
