import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { mergeJsonColumn } from "@ai-matrx/data/db";
import { waitForConversationPersisted } from "../conversations/conversation-persistence.js";
import {
  markInputCapabilitiesPersisted,
  markInputCapabilitiesPersistenceError
} from "./instance-input-capabilities.slice.js";
import {
  UI_GATE_KEYS,
  parseUiGates
} from "../../agent-settings/ui-gates.js";
import { hasBrowserSession } from "../../../../host/identity.js";
function serializableUiGates(source) {
  const result = {};
  for (const key of UI_GATE_KEYS) {
    const value = source[key];
    if (typeof value === "boolean") result[key] = value;
  }
  return result;
}
function parsePersistedInputCapabilities(metadata) {
  if (!metadata || typeof metadata !== "object" || Array.isArray(metadata)) {
    return { overrides: {} };
  }
  const block = Reflect.get(metadata, "input_capabilities");
  if (!block || typeof block !== "object" || Array.isArray(block)) {
    return { overrides: {} };
  }
  return { overrides: parseUiGates(Reflect.get(block, "overrides")) };
}
const persistInputCapabilities = createAsyncThunk(
  "instanceInputCapabilities/persist",
  async ({ conversationId }, { dispatch, getState }) => {
    if (!await hasBrowserSession()) return;
    const persisted = await waitForConversationPersisted(conversationId);
    if (!persisted) {
      const error2 = "Conversation is not available for capability persistence";
      console.error(`[input-capabilities] ${error2}: ${conversationId}`);
      dispatch(
        markInputCapabilitiesPersistenceError({ conversationId, error: error2 })
      );
      return;
    }
    for (let attempt = 0; attempt < 5; attempt++) {
      const entry = getState().instanceInputCapabilities.byConversationId[conversationId];
      if (!entry) return;
      const overrides = serializableUiGates(entry.overrides);
      const serialized = JSON.stringify(overrides);
      const result = await mergeJsonColumn({
        fetchCurrent: () => supabase.schema("chat").from("conversation").select("id, version, metadata").eq("id", conversationId).is("deleted_at", null).maybeSingle(),
        readColumn: (row) => row.metadata,
        merge: (current) => ({
          ...current,
          input_capabilities: { overrides }
        }),
        applyUpdate: ({ value, expectedVersion, nextVersion }) => supabase.schema("chat").from("conversation").update({ metadata: value, version: nextVersion }).eq("id", conversationId).eq("version", expectedVersion).select("id, version, metadata").maybeSingle()
      });
      if (result.status !== "saved") {
        const error2 = result.status === "error" ? String(result.error) : `metadata write ${result.status}`;
        console.error(
          `[input-capabilities] Failed to persist ${conversationId}: ${error2}`
        );
        dispatch(
          markInputCapabilitiesPersistenceError({ conversationId, error: error2 })
        );
        return;
      }
      const latest = getState().instanceInputCapabilities.byConversationId[conversationId];
      if (latest && JSON.stringify(serializableUiGates(latest.overrides)) === serialized) {
        dispatch(markInputCapabilitiesPersisted(conversationId));
        return;
      }
    }
    const error = "Input capabilities changed faster than they could persist";
    console.error(`[input-capabilities] ${error}: ${conversationId}`);
    dispatch(markInputCapabilitiesPersistenceError({ conversationId, error }));
  }
);
export {
  parsePersistedInputCapabilities,
  persistInputCapabilities
};
