import { createAsyncThunk } from "@reduxjs/toolkit";
import { extractErrorMessage } from "@ai-matrx/data/net";
import { submitToolResult } from "../../api/submit-tool-results.js";
import { upsertToolLifecycle } from "../../redux/execution-system/active-requests/active-requests.slice.js";
import { getUiFirstToolEntry } from "../tools/registry.js";
const dispatchUiFirstTool = createAsyncThunk(
  "uiFirstTools/dispatch",
  async ({ conversationId, requestId, callId, toolName, args }, { dispatch, getState }) => {
    const state = getState();
    const userId = state.userAuth?.id ?? null;
    if (!userId) {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType: "unauthenticated",
          errorMessage: "user not authenticated",
          result: { ok: false, reason: "unauthenticated" }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: { ok: false, reason: "unauthenticated" },
          error_message: "user not authenticated"
        })
      );
      return;
    }
    const entry = getUiFirstToolEntry(toolName);
    if (!entry) {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType: "unknown_tool",
          errorMessage: `Unknown ui-first tool: ${toolName}`,
          result: { ok: false, reason: "unknown_tool" }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: { ok: false, reason: "unknown_tool" },
          error_message: `Unknown ui-first tool: ${toolName}`
        })
      );
      return;
    }
    const parsed = entry.schema.safeParse(args);
    if (!parsed.success) {
      const message = `args failed schema for ${toolName}: ${JSON.stringify(
        parsed.error.format()
      )}`;
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType: "schema",
          errorMessage: message,
          result: { ok: false, reason: "schema", message }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: { ok: false, reason: "schema", message },
          error_message: message
        })
      );
      return;
    }
    const startedAt = performance.now();
    try {
      const result = await entry.handler.run(parsed.data, {
        conversationId,
        callId,
        userId,
        dispatch,
        getState
      });
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "completed",
          isDelegated: true,
          result
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: false,
          output: result,
          duration_ms: Math.round(performance.now() - startedAt)
        })
      );
    } catch (cause) {
      const message = extractErrorMessage(cause);
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType: "handler_threw",
          errorMessage: message,
          result: { ok: false, reason: "handler_threw", message }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: { ok: false, reason: "handler_threw", message },
          error_message: message,
          duration_ms: Math.round(performance.now() - startedAt)
        })
      );
    }
  }
);
export {
  dispatchUiFirstTool
};
