import { callbackManager } from "../../../../utils/callbackManager.js";
import {
  deriveClientToolsFromHandle
} from "../../../types/widget-handle.types.js";
import { selectWidgetHandleIdFor } from "../instance-ui-state/instance-ui-state.selectors.js";
import {
  isToolBlocked,
  selectBlockedToolPatterns
} from "../utils/shortcut-tool-block.js";
import { registerClientCapability } from "./registry.js";
registerClientCapability({
  name: "widget-handle",
  selectPayload: (state, conversationId) => {
    const handleId = selectWidgetHandleIdFor(state, conversationId);
    const handle = handleId ? callbackManager.get(handleId) : null;
    const blocked = selectBlockedToolPatterns(state, conversationId);
    const tools = deriveClientToolsFromHandle(handle).filter(
      (name) => !isToolBlocked(name, blocked)
    );
    return tools.length > 0 ? { tools } : null;
  }
});
