const WAR_ROOM_TOOL_NAMES = [
  "war_room_update_task",
  "war_room_add_subtask",
  "war_room_toggle_subtask",
  "war_room_update_note",
  "war_room_update_thread"
];
function isWarRoomToolName(name) {
  return WAR_ROOM_TOOL_NAMES.includes(name);
}
export {
  WAR_ROOM_TOOL_NAMES,
  isWarRoomToolName
};
