function selectBlockedToolPatterns(state, conversationId) {
  const shortcutId = state.conversations?.byConversationId?.[conversationId]?.shortcutId ?? null;
  if (!shortcutId) return [];
  return state.agentShortcut?.shortcuts?.[shortcutId]?.neverIncludeTools ?? [];
}
function isToolBlocked(name, patterns) {
  return patterns.some(
    (pattern) => pattern.endsWith("*") ? name.startsWith(pattern.slice(0, -1)) : name === pattern
  );
}
