import { createAsyncThunk } from "@reduxjs/toolkit";
import { extractErrorMessage } from "@ai-matrx/data/net";
import { submitToolResult } from "../../api/submit-tool-results.js";
import { upsertToolLifecycle } from "../../redux/execution-system/active-requests/active-requests.slice.js";
import { getScribeToolEntry } from "../tools/registry.js";
import { isScribeToolName } from "../tools/names.js";
const dispatchScribeTool = createAsyncThunk(
  "scribeTools/dispatch",
  async ({ conversationId, requestId, callId, toolName, args }, { dispatch, getState }) => {
    const state = getState();
    const userId = state.userAuth?.id ?? null;
    const fail = (errorType, message, durationMs) => {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType,
          errorMessage: message,
          result: { ok: false, reason: errorType, message }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: { ok: false, reason: errorType, message },
          error_message: message,
          ...durationMs !== void 0 ? { duration_ms: durationMs } : {}
        })
      );
    };
    const complete = (output, durationMs) => {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "completed",
          isDelegated: true,
          result: output
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: false,
          output,
          duration_ms: durationMs
        })
      );
    };
    if (!userId) {
      fail("unauthenticated", "user not authenticated");
      return;
    }
    if (!isScribeToolName(toolName)) {
      fail("unknown_tool", `Unknown scribe tool: ${toolName}`);
      return;
    }
    const entry = getScribeToolEntry(toolName);
    if (!entry) {
      fail("unknown_tool", `Unknown scribe tool: ${toolName}`);
      return;
    }
    const parsed = entry.schema.safeParse(args);
    if (!parsed.success) {
      fail(
        "schema",
        `args failed schema for ${toolName}: ${JSON.stringify(
          parsed.error.format()
        )}`
      );
      return;
    }
    const startedAt = performance.now();
    try {
      const result = await entry.handler.run(parsed.data, {
        conversationId,
        callId,
        userId,
        dispatch,
        getState
      });
      complete(
        result,
        Math.round(performance.now() - startedAt)
      );
    } catch (cause) {
      fail(
        "handler_threw",
        extractErrorMessage(cause),
        Math.round(performance.now() - startedAt)
      );
    }
  }
);
export {
  dispatchScribeTool
};
