import { createAsyncThunk } from "@reduxjs/toolkit";
import { extractErrorMessage } from "@ai-matrx/data/net";
import { submitToolResult } from "../../../api/submit-tool-results.js";
import { upsertToolLifecycle } from "../active-requests/active-requests.slice.js";
import { executeSurfaceClientTool } from "../../../../surfaces/runtime/surface-client-tools.js";
import { createSurfaceToolCall } from "./surface-tool-call.js";
const dispatchSurfaceClientTool = createAsyncThunk(
  "surfaceClientTools/dispatch",
  async ({ conversationId, requestId, callId, toolName, args }, { dispatch, getState }) => {
    const startedAt = performance.now();
    const finish = (output, errorMessage) => {
      const durationMs = Math.round(performance.now() - startedAt);
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: errorMessage ? "error" : "completed",
          isDelegated: true,
          result: output,
          ...errorMessage ? {
            errorType: "surface_client_tool_failed",
            errorMessage
          } : {}
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: Boolean(errorMessage),
          output,
          duration_ms: durationMs,
          ...errorMessage ? { error_message: errorMessage } : {}
        })
      );
    };
    try {
      const call = await createSurfaceToolCall({
        conversationId,
        callId,
        toolName,
        dispatch,
        getState
      });
      const result = await executeSurfaceClientTool(toolName, args, { call });
      if (result.ok) {
        finish({
          ok: true,
          surface_name: result.surfaceName,
          output: result.output ?? null
        });
      } else {
        finish(
          { ok: false, reason: "surface_client_tool_failed", message: result.error },
          result.error
        );
      }
    } catch (cause) {
      const message = extractErrorMessage(cause);
      console.error(
        `[surface-client-tools] runtime threw for '${toolName}' \u2014 contract break`,
        cause
      );
      finish(
        { ok: false, reason: "surface_client_tool_runtime_threw", message },
        message
      );
    }
  }
);
export {
  dispatchSurfaceClientTool
};
