import { createAsyncThunk } from "@reduxjs/toolkit";
import { durableRecordId } from "@ai-matrx/kit/ids";
import { supabase } from "../../../../host/db.js";
import { updateMessageRecord } from "../messages/messages.slice.js";
import { selectConversationMessages } from "../messages/messages.selectors.js";
import { hasHandlelessRemark, withPersistedHandles } from "../instance-resources/remark-handles.js";
const RETRY_DELAYS_MS = [0, 400, 1e3, 2e3];
const stampPersistedRemarkHandles = createAsyncThunk(
  "messages/stampPersistedRemarkHandles",
  async ({ conversationId }, { dispatch, getState }) => {
    const wanted = () => selectConversationMessages(conversationId)(getState()).filter(
      (m) => m.role === "user" && durableRecordId(m.id) !== null && (hasHandlelessRemark(m.content) || hasHandlelessRemark(m.userContent))
    );
    let stamped = 0;
    for (const delay of RETRY_DELAYS_MS) {
      if (delay) await new Promise((resolve) => setTimeout(resolve, delay));
      const pending = wanted();
      if (pending.length === 0) break;
      for (const message of pending) {
        const { data, error } = await supabase.schema("chat").from("message").select("content, user_content").eq("id", message.id).is("deleted_at", null).maybeSingle();
        if (error) {
          console.error("[stampPersistedRemarkHandles] read failed:", error.message);
          continue;
        }
        if (!data) continue;
        const persisted = [data.content, data.user_content];
        const patch = {};
        for (const source of persisted) {
          const content = withPersistedHandles(message.content, source);
          if (content) patch.content = content;
          const userContent = withPersistedHandles(message.userContent, source);
          if (userContent) patch.userContent = userContent;
        }
        if (patch.content || patch.userContent) {
          dispatch(updateMessageRecord({ conversationId, messageId: message.id, patch }));
          stamped += 1;
        }
      }
      if (wanted().length === 0) break;
    }
    return stamped;
  }
);
export {
  stampPersistedRemarkHandles
};
