import { createOpener } from "@ai-matrx/kit/opener";
const valuePromptsOpener = createOpener("matrx-frontend.value-prompts-opener-state", {
  hostHint: "<ValuePromptsDialogHost /> (mounted once in app/Providers.tsx)"
});
function promptForValues(req) {
  return valuePromptsOpener.open(req);
}
export {
  promptForValues,
  valuePromptsOpener
};
