import { createAsyncThunk } from "@reduxjs/toolkit";
import { callbackManager } from "../../../../utils/callbackManager.js";
import { extractErrorMessage } from "@ai-matrx/data/net";
import {
  WIDGET_TOOL_NAME_TO_HANDLE_METHOD
} from "../../../types/widget-handle.types.js";
import { selectWidgetHandleIdFor } from "../instance-ui-state/instance-ui-state.selectors.js";
import { submitToolResult } from "../../../api/submit-tool-results.js";
import { upsertToolLifecycle } from "../active-requests/active-requests.slice.js";
import { setInstanceStatus } from "../conversations/conversations.slice.js";
import { requestInlineApproval } from "../../../ui-first-tools/redux/request-approval.js";
import { personDeclinedToolOutput } from "../../../api/person-declined-tool-output.js";
import { resolveAgentName } from "../../../../surfaces/hooks/useAgentNames.js";
import { selectAgentById } from "../../agent-definition/selectors.js";
import { buildWidgetActionApprovalChange } from "./widget-action-approval-change.js";
const dispatchWidgetAction = createAsyncThunk(
  "widgetAction/dispatch",
  async ({ conversationId, requestId, callId, toolName, args }, { dispatch, getState }) => {
    const state = getState();
    const handleId = selectWidgetHandleIdFor(state, conversationId);
    const handle = handleId ? callbackManager.get(handleId) : null;
    const startedAt = performance.now();
    let result;
    if (!handle) {
      result = {
        ok: false,
        reason: "not_found",
        message: `No widget handle registered for conversation ${conversationId}`
      };
    } else {
      const methodKey = WIDGET_TOOL_NAME_TO_HANDLE_METHOD[toolName];
      const method = handle[methodKey];
      if (typeof method !== "function") {
        result = {
          ok: false,
          reason: "unsupported",
          message: `Widget handle does not implement ${methodKey}`
        };
        handle.onError?.({
          reason: "unsupported",
          message: `Widget handle does not implement ${methodKey}`
        });
      } else {
        const decision = await askPerson({
          handle,
          conversationId,
          callId,
          toolName,
          args,
          dispatch,
          getState
        });
        if (decision.kind !== "approved") {
          const output = personDeclinedToolOutput({
            reason: decision.kind === "cancelled" ? "skipped" : "kept_as_is",
            message: decision.kind === "cancelled" ? "The person closed the approval without deciding. Nothing was changed." : "The person kept the text as is. Nothing was changed \u2014 do not retry this edit.",
            ...decision.kind === "instructions" ? { instructions: decision.text } : {}
          });
          dispatch(
            upsertToolLifecycle({
              requestId,
              callId,
              toolName,
              status: "completed",
              isDelegated: true,
              result: output
            })
          );
          dispatch(
            submitToolResult({
              conversationId,
              call_id: callId,
              tool_name: toolName,
              is_error: false,
              output,
              duration_ms: Math.round(performance.now() - startedAt)
            })
          );
          return { ok: false, reason: "declined", message: output.message };
        }
        try {
          await method(args);
          result = { ok: true, applied: toolName };
        } catch (cause) {
          const message = extractErrorMessage(cause);
          result = {
            ok: false,
            reason: "failed",
            message,
            cause
          };
          handle.onError?.({
            reason: "failed",
            message,
            cause
          });
        }
      }
    }
    const finalResult = result;
    if (finalResult.ok === true) {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "completed",
          isDelegated: true,
          result: { ok: true, applied: finalResult.applied }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: false,
          output: { ok: true, applied: finalResult.applied },
          duration_ms: Math.round(performance.now() - startedAt)
        })
      );
    } else {
      dispatch(
        upsertToolLifecycle({
          requestId,
          callId,
          toolName,
          status: "error",
          isDelegated: true,
          errorType: finalResult.reason,
          errorMessage: finalResult.message,
          result: {
            ok: false,
            reason: finalResult.reason,
            message: finalResult.message
          }
        })
      );
      dispatch(
        submitToolResult({
          conversationId,
          call_id: callId,
          tool_name: toolName,
          is_error: true,
          output: {
            ok: false,
            reason: finalResult.reason,
            message: finalResult.message
          },
          error_message: finalResult.message ?? finalResult.reason,
          duration_ms: Math.round(performance.now() - startedAt)
        })
      );
    }
    return result;
  }
);
async function askPerson({
  handle,
  conversationId,
  callId,
  toolName,
  args,
  dispatch,
  getState
}) {
  if (handle.applyPolicy === "auto") return { kind: "approved" };
  const state = getState();
  const agentId = state.conversations.byConversationId[conversationId]?.agentId;
  const actorLabel = agentId ? await resolveAgentName(agentId) ?? selectAgentById(state, agentId)?.name : void 0;
  let currentText = null;
  try {
    currentText = handle.readText?.() ?? null;
  } catch {
    currentText = null;
  }
  const change = buildWidgetActionApprovalChange({
    toolName,
    args,
    ...actorLabel ? { actorLabel } : {},
    currentText
  });
  dispatch(setInstanceStatus({ conversationId, status: "paused" }));
  const decision = await requestInlineApproval({
    conversationId,
    callId,
    toolName,
    change,
    dispatch
  });
  return decision.kind === "approved" ? { kind: "approved" } : decision;
}
export {
  dispatchWidgetAction
};
