const UI_FIRST_TOOL_NAMES = [
  // `user` was RETIRED 2026-10-04 — `ask_person` (server-run) is the one way
  // to ask the person; every client renders it through this chat package.
  "update_plan",
  "request_user_takeover",
  // NOTE: `tasks` was removed 2026-07-22 — it moved from client-delegated to
  // server-executed in aidream (aidream/tools/agent_tasks_tool.py). It was a pure
  // chat.agent_task write with no client-only work, and delegating it stalled the
  // loop on every task update. The TaskPanel still renders the list via its
  // Supabase Realtime subscription; the agent's writes now happen server-side.
  "user_todos",
  // The reviewed Gmail send. Client-only BY DESIGN: it has no server executor,
  // so the only way this message can be sent is the user confirming the exact
  // bytes in <GmailReviewCard>.
  "google_email_send"
];
function isUiFirstToolName(name) {
  return UI_FIRST_TOOL_NAMES.includes(name);
}
export {
  UI_FIRST_TOOL_NAMES,
  isUiFirstToolName
};
