import { hostFn, hostSlot } from "./ui-slots.js";
import { listOrgParam } from "@ai-matrx/records/list";
import { supabase } from "./db.js";
const CONVERSATION_ANCHOR_TYPE = "conversation";
const contentIrKindValidator = hostFn("contentIrKindValidator", () => ({
  validate: async (_value, kind) => ({
    kind,
    checked: false,
    ok: false,
    errors: ["This host has no kind catalog to check against (registerChatUi contentIrKindValidator)."],
    degradedReason: "catalog_unreachable"
  }),
  cachedSchema: async () => null,
  invalidate: () => void 0
}));
const AnchorRecordsList = hostSlot("AnchorRecordsList");
const useAnchorRecords = hostFn("useAnchorRecords", () => ({
  status: "ready",
  records: [],
  active: [],
  archived: [],
  message: null,
  reload: () => void 0
}));
async function readShapePage(query, sort) {
  const { data, error } = await supabase.rpc("shx_list_scoped", {
    p_scope: query.scope.kind,
    p_org_id: listOrgParam(query),
    p_search: query.search.trim() || void 0,
    p_deep: query.deep,
    p_sort: sort.sort,
    p_dir: sort.direction,
    p_filters: query.filters,
    p_limit: sort.pageSize,
    p_offset: (query.page - 1) * sort.pageSize
  });
  if (error) throw new Error(`Could not load the shapes: ${error.message ?? "the database returned an error with no message."}`);
  const rows = data ?? [];
  return { rows, total: rows.length > 0 ? Number(rows[0].total_count) : 0 };
}
const fetchShapePage = hostFn("fetchShapePage", readShapePage);
const fetchShapeByKind = hostFn("fetchShapeByKind", async (kind) => {
  const page = await readShapePage(
    { scope: { kind: "all" }, orgId: null, search: "", deep: false, archived: "active", filters: { kind: { kind: "text", value: kind } }, page: 1 },
    { sort: "label", direction: "asc", favoritesFirst: false, pageSize: 50 }
  );
  return page.rows.find((row) => row.kind === kind) ?? null;
});
const useOpenCitationSource = hostFn("useOpenCitationSource", () => (source) => {
  if (source.url && typeof window !== "undefined") window.open(source.url, "_blank", "noopener,noreferrer");
});
const FullScreenMarkdownEditor = hostSlot("FullScreenMarkdownEditor");
export {
  AnchorRecordsList,
  CONVERSATION_ANCHOR_TYPE,
  FullScreenMarkdownEditor,
  contentIrKindValidator,
  fetchShapeByKind,
  fetchShapePage,
  useAnchorRecords,
  useOpenCitationSource
};
