import { getLiveDesktopInstance } from "./desktop-presence.js";
import { registerClientCapability } from "./registry.js";
import { isChatHostConfigured, onChatHostConfigured } from "../../../../host/configure.js";
function toSysPlatform(platform) {
  return platform === "windows" ? "win32" : platform;
}
const PRESENCE_BUDGET_MS = 150;
if (typeof window !== "undefined") {
  const warm = () => setTimeout(() => void getLiveDesktopInstance(), 0);
  if (isChatHostConfigured()) {
    warm();
  } else {
    const stop = onChatHostConfigured(() => {
      stop();
      warm();
    });
  }
}
registerClientCapability({
  name: "desktop-native",
  selectPayload: async () => {
    const desktop = await Promise.race([
      getLiveDesktopInstance(),
      new Promise((resolve) => setTimeout(() => resolve(null), PRESENCE_BUDGET_MS))
    ]);
    if (!desktop) return null;
    return {
      platform: toSysPlatform(desktop.platform),
      engine_version: desktop.engineVersion,
      instance_id: desktop.instanceId,
      tunnel_state: desktop.tunnelActive ? "active" : "none"
    };
  }
});
