import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { tryWriteOne } from "@ai-matrx/data/db";
import { waitForConversationPersisted } from "../conversations/conversation-persistence.js";
function parsePersistedHostValueNames(row) {
  const raw = row?.host_value_names;
  if (!Array.isArray(raw)) return [];
  return raw.filter((name) => typeof name === "string");
}
const persistVariableAuthorship = createAsyncThunk(
  "instanceVariableValues/persistAuthorship",
  async ({ conversationId, names: atSubmit }, { getState }) => {
    const names = [
      ...atSubmit ?? getState().instanceVariableValues.byConversationId[conversationId]?.hostValueNames ?? []
    ];
    if (names.length === 0) return;
    const persisted = await waitForConversationPersisted(conversationId);
    if (!persisted) {
      console.error(
        `[variable-authorship] Conversation ${conversationId} never materialised \u2014 the values its surface wired will read back as the person's own words when it is reopened. Retry by sending another turn.`
      );
      return;
    }
    const { error } = await tryWriteOne(
      supabase.schema("chat").from("conversation").update({ host_value_names: names }).eq("id", conversationId).select("id"),
      { action: "save", noun: "conversation" }
    );
    if (error) {
      console.error(
        `[variable-authorship] Failed to record authorship for ${conversationId}: ${error.message}. On reload this conversation will show the host's launch values inside the person's own message bubble.`
      );
    }
  }
);
export {
  parsePersistedHostValueNames,
  persistVariableAuthorship
};
